evidence.command:
set -e; D=$(mktemp -d); ln -s ~/.volta/tools/image/packages/@deepseek-ai/dsh/lib/node_modules/@deepseek-ai/dsh/node_modules "$D/node_modules"; cat > "$D/prune.mjs" <<'PRUNE'
import { Context } from '@deepseek-ai/cordis';
import { Session } from '@deepseek-ai/dsh-session';
import { createToolResultMessage } from '@deepseek-ai/dsh-llm';
import ToolResultPruner from '@deepseek-ai/dsh-compaction-tool-result-pruner';
import TokenMeter from '@deepseek-ai/dsh-token-meter';
const ctx = new Context();
ctx.plugin(TokenMeter, {});
ctx.plugin(ToolResultPruner, {});
await new Promise(r => setTimeout(r, 300));
console.log('pruner_service=' + (ctx.toolResultPruner ? 'mounted' : 'MISSING'));
console.log('thresholdChars=' + ctx.toolResultPruner.config.thresholdChars);
const session = Session.create('m0-5-fixture');
const big = 'X'.repeat(20000);
const msg = createToolResultMessage({ callId: 'call_m0_5', content: [{ type:'text', text: big }], isError: false });
const META = { evidence_anchor: { cas_sha256: 'a'.repeat(64), fetched_at: '2026-08-17T00:00:00Z', nested: { deep: [1,2,{ k:'v' }] } } };
const appended = session.append('tool/result', { turn:1, step:1, message: msg, meta: META }, { surfaceOp:'append' });
console.log('appended_seq=' + appended.seq);
console.log('surface_nodes_before=' + JSON.stringify([...session.surface.nodes]));
const result = ctx.toolResultPruner.pruneSession(session);
console.log('pruned_count=' + result.pruned.length);
console.log('charsRemoved=' + result.charsRemoved);
console.log('surface_nodes_after=' + JSON.stringify([...session.surface.nodes]));
const repl = session.events[result.pruned[0].replacementSeq];
console.log('replacement_event_type=' + repl.type);
console.log('replacement_surfaceOp=' + JSON.stringify(repl.surfaceOp));
console.log('replacement_has_meta=' + (repl.data.meta !== undefined));
console.log('replacement_meta_byte_identical=' + (JSON.stringify(repl.data.meta) === JSON.stringify(META)));
console.log('replacement_content_len=' + repl.data.message.content[0].content[0].text.length);
console.log('original_content_len=' + session.events[appended.seq].data.message.content[0].content[0].text.length);
console.log('original_event_still_present=' + (session.events[appended.seq].type === 'tool/result'));
console.log('original_meta_intact=' + (JSON.stringify(session.events[appended.seq].data.meta) === JSON.stringify(META)));
console.log('all_event_types=' + JSON.stringify(session.events.map(e => e.type)));
process.exit(0);
PRUNE
cd "$D" && node --no-warnings "$D/prune.mjs" > /tmp/m0-5-verify.txt 2>&1; shasum -a 256 /tmp/m0-5-verify.txt; rm -rf "$D"
